from dataclasses import dataclass
from typing import TypeVar, Generic, Union

T = TypeVar('T')

@dataclass(frozen=True, repr=False)
class Some(Generic[T]):
    value: T
    def __repr__(self) -> str:
        return f"Some({self.value})"

@dataclass(frozen=True, repr=False)
class Nothing:
    def __repr__(self) -> str:
        return "None"

Option = Union[Some[T], Nothing]
NONE = Nothing()

def safe_divide(numerator: float, divisor: float) -> Option[float]:
    """
    Safely divides two numbers.
    Returns Some(result) for a valid division, or NONE for division by zero.
    """
    if divisor == 0:
        return NONE
    return Some(numerator / divisor)

def main():
    """Tests the safe_divide function and prints results."""
    # Test case 1: Successful division
    result1 = safe_divide(10, 2)
    if isinstance(result1, Some):
        print(f"Result: {result1.value}")
    elif isinstance(result1, Nothing):
        print("Error: Division by zero")

    # Test case 2: Division by zero
    result2 = safe_divide(10, 0)
    if isinstance(result2, Some):
        print(f"Result: {result2.value}")
    elif isinstance(result2, Nothing):
        print("Error: Division by zero")

if __name__ == "__main__":
    main()

