from typing import TypeVar, Generic, Callable
from dataclasses import dataclass

T = TypeVar('T')
U = TypeVar('U')

class Result(Generic[T]):
    """Base class for Result type. Not meant to be instantiated directly."""
    def and_then(self, op: Callable[[T], 'Result[U]']) -> 'Result[U]':
        raise NotImplementedError

@dataclass(frozen=True)
class Ok(Result[T]):
    value: T
    __match_args__ = ('value',)

    def and_then(self, op: Callable[[T], 'Result[U]']) -> 'Result[U]':
        return op(self.value)

@dataclass(frozen=True)
class Err(Result[T]):
    message: str
    __match_args__ = ('message',)

    def and_then(self, op: Callable[[T], 'Result[U]']) -> 'Result[U]':
        return self

def parse_int(s: str) -> Result[int]:
    """Parses a string into an integer, returning a Result."""
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    """Performs integer division, returning a Result."""
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def process_and_print(result: Result):
    """Processes a Result and prints the outcome."""
    match result:
        case Ok(value):
            print(f"Result: {value}")
        case Err(msg):
            print(f"Error: {msg}")

def main():
    # Test case 1: Successful parsing and division
    result1 = parse_int("10").and_then(lambda x: divide_safe(x, 2))
    process_and_print(result1)

    # Test case 2: Successful parsing, but division by zero
    result2 = parse_int("10").and_then(lambda x: divide_safe(x, 0))
    process_and_print(result2)

    # Test case 3: Failed parsing, division is short-circuited
    result3 = parse_int("abc").and_then(lambda x: divide_safe(x, 2))
    process_and_print(result3)

if __name__ == "__main__":
    main()

